SysDataModelXML.JavaScript:
scan_para=function(id, r){
  if(id=="linkinput"){
    scan_impl(id, "#"+r+"#");}
  else{
    document.getElementById(id).value=r;
  }
};

//扫码返回刷新
Save_Data = function() {
   if($("#已扫箱数").length){
    var index = plus.webview.getWebviewById("contentlist");
    mui.fire(index, "contentlist_local", {
        para: index.modelParams
    });}
}

//隐藏保存按钮
//$("#linkok").hide();

//扫描后自动保存
scanAfterAction = function(r) {
  var dataCheck = $("#数据检查").val();
  
  // 数据检查
  if (dataCheck && dataCheck.trim() !== "") {
    alert(dataCheck);
    keep_focus("linkinput");
    return;
  } else {
    // 数据检查通过，执行自动保存
    recSave(globleServer, globleDmCode, globleDmNum, dataSumitScriptType, "","autoSave","autoSave");
  }
}

afterFunction = function (sta, id) {
    alert(id + "===" + sta);
    if (id == "autoSave" && sta == "autoSave")
        setTimeout(function () {
            keep_focus("linkinput");
        }, 100);
    if (sta == "linkquick12")
        reloadModelData()
};

beforeFunction = function(sta, id) {
   if(id=="linkok")return false;
    var checkData = $("#数据检查").val();
    
    // 只有在特定状态下才检查数据
    if (checkData !== "" && (sta === "new" || sta === "autoSave")) {
        alert(checkData);
        return true;  // 拦截操作
    }
    
    return false;  // 继续执行
};


afterFunction=function(sta,id){//执行后处理
	if(id=="linkok"&&$("#已扫箱数").val()!=$("#已扫箱数1").val()){
		playAudio("_www/libs/audio/error.wav");
        }
}
